CREATE TABLE users (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, role VARCHAR(31) NOT NULL CHECK(role IN ('EMPLOYEE','TECHNICIAN','ADMIN')),
 email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, name VARCHAR(255) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
 available BOOLEAN DEFAULT TRUE,max_workload INTEGER DEFAULT 8 CHECK(max_workload BETWEEN 1 AND 100),experience_years INTEGER DEFAULT 0 CHECK(experience_years BETWEEN 0 AND 60)
);
CREATE UNIQUE INDEX users_email_ci ON users(lower(email));
CREATE TABLE skills(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(255) NOT NULL UNIQUE);
CREATE TABLE technician_skills(technician_id BIGINT REFERENCES users(id),skill_id BIGINT REFERENCES skills(id),PRIMARY KEY(technician_id,skill_id));
CREATE TABLE services(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(255) NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE,criticality INTEGER NOT NULL CHECK(criticality BETWEEN 1 AND 3),required_skill VARCHAR(255) NOT NULL);
CREATE TABLE incident_categories(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,name VARCHAR(255) NOT NULL UNIQUE,active BOOLEAN NOT NULL DEFAULT TRUE,required_skill VARCHAR(255) NOT NULL);
CREATE TABLE sla_policies(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,priority VARCHAR(255) NOT NULL UNIQUE CHECK(priority IN ('P1','P2','P3','P4')),response_minutes INTEGER NOT NULL CHECK(response_minutes>0),resolution_minutes INTEGER NOT NULL CHECK(resolution_minutes>=response_minutes));
CREATE TABLE system_settings(id BIGINT PRIMARY KEY CHECK(id=1),assignment_strategy VARCHAR(255) NOT NULL,priority_strategy VARCHAR(255) NOT NULL,p1threshold DOUBLE PRECISION NOT NULL,p2threshold DOUBLE PRECISION NOT NULL,p3threshold DOUBLE PRECISION NOT NULL,email_enabled BOOLEAN NOT NULL,CHECK(p1threshold>p2threshold AND p2threshold>p3threshold AND p3threshold>0));
CREATE TABLE incidents (
 id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,version BIGINT NOT NULL DEFAULT 0,title VARCHAR(255) NOT NULL,description TEXT NOT NULL,
 reporter_id BIGINT NOT NULL REFERENCES users(id),technician_id BIGINT REFERENCES users(id),service_id BIGINT NOT NULL REFERENCES services(id),category_id BIGINT NOT NULL REFERENCES incident_categories(id),sla_policy_id BIGINT REFERENCES sla_policies(id),
 impact INTEGER NOT NULL CHECK(impact BETWEEN 1 AND 3),urgency INTEGER NOT NULL CHECK(urgency BETWEEN 1 AND 3),affected_users INTEGER NOT NULL CHECK(affected_users BETWEEN 1 AND 1000000),priority_score DOUBLE PRECISION NOT NULL DEFAULT 0,priority VARCHAR(255),priority_reason VARCHAR(255),assignment_reason VARCHAR(255),
 status VARCHAR(255) NOT NULL CHECK(status IN ('NEW','CLASSIFIED','ASSIGNED','ACKNOWLEDGED','IN_PROGRESS','RESOLVED','VERIFIED','CLOSED')),
 created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,response_deadline TIMESTAMPTZ,resolution_deadline TIMESTAMPTZ,acknowledged_at TIMESTAMPTZ,resolved_at TIMESTAMPTZ,verified_at TIMESTAMPTZ,closed_at TIMESTAMPTZ,
 response_violated BOOLEAN NOT NULL DEFAULT FALSE,resolution_violated BOOLEAN NOT NULL DEFAULT FALSE,warning_level VARCHAR(255) NOT NULL DEFAULT 'SAFE',resolution_details TEXT,verification_details TEXT
);
CREATE INDEX incidents_reporter ON incidents(reporter_id,created_at DESC);
CREATE INDEX incidents_technician_status ON incidents(technician_id,status);
CREATE INDEX incidents_filters ON incidents(status,priority,category_id,service_id);
CREATE INDEX incidents_deadlines ON incidents(resolution_deadline) WHERE status NOT IN ('RESOLVED','VERIFIED','CLOSED');
CREATE TABLE incident_notes(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,incident_id BIGINT NOT NULL REFERENCES incidents(id),author_id BIGINT NOT NULL REFERENCES users(id),content TEXT NOT NULL,information_request BOOLEAN NOT NULL,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE incident_assignments(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,incident_id BIGINT REFERENCES incidents(id),technician_id BIGINT REFERENCES users(id),assigned_by_id BIGINT REFERENCES users(id),reason VARCHAR(255),created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE audit_logs(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,incident_id BIGINT REFERENCES incidents(id),actor_id BIGINT REFERENCES users(id),action VARCHAR(255) NOT NULL,previous_state VARCHAR(255),new_state VARCHAR(255),description TEXT,created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX audit_incident_time ON audit_logs(incident_id,created_at);
CREATE TABLE feedback(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,incident_id BIGINT NOT NULL UNIQUE REFERENCES incidents(id),rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),comment TEXT,created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE duplicate_suggestions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,incident_id BIGINT NOT NULL REFERENCES incidents(id),related_id BIGINT NOT NULL REFERENCES incidents(id),score DOUBLE PRECISION NOT NULL CHECK(score BETWEEN 0 AND 1),decision VARCHAR(255) NOT NULL DEFAULT 'PENDING' CHECK(decision IN ('PENDING','CONFIRMED','REJECTED')),reviewed_by_id BIGINT REFERENCES users(id),reviewed_at TIMESTAMPTZ,UNIQUE(incident_id,related_id),CHECK(incident_id<>related_id));
CREATE TABLE notifications(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,recipient_id BIGINT NOT NULL REFERENCES users(id),incident_id BIGINT REFERENCES incidents(id),event_type VARCHAR(255),message TEXT NOT NULL,read BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMPTZ NOT NULL);
CREATE INDEX notification_recipient ON notifications(recipient_id,created_at DESC);
CREATE TABLE email_outbox(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,recipient VARCHAR(255) NOT NULL,subject VARCHAR(255) NOT NULL,body TEXT NOT NULL,delivery_status VARCHAR(255) NOT NULL,created_at TIMESTAMPTZ NOT NULL);
CREATE FUNCTION protect_audit_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit history is append-only'; END $$;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION protect_audit_history();
